import { Effect } from "effect"
import * as SnapshotStore from "../services/SnapshotStore.js"

export interface SnapshotInput {
  readonly catalogId: string
  readonly revision: string
  readonly entries: ReadonlyArray<{
    readonly sku: string
    readonly price: number
  }>
}

export interface PublishRequest {
  readonly batchId: string
  readonly snapshots: ReadonlyArray<SnapshotInput>
}

export const publishSnapshots = (request: PublishRequest) =>
  Effect.gen(function*() {
    const store = yield* SnapshotStore.SnapshotStore

    // Writes are limited by SnapshotStore.layerWriteLimit.
    const receipts = yield* Effect.forEach(
      request.snapshots,
      (snapshot) =>
        store.write({
          key: `${snapshot.catalogId}/${snapshot.revision}.json`,
          body: JSON.stringify(snapshot.entries),
          contentType: "application/json",
          metadata: { batchId: request.batchId }
        }),
      { concurrency: "unbounded" }
    )

    return {
      batchId: request.batchId,
      objects: receipts.map((receipt, index) => ({
        catalogId: request.snapshots[index]!.catalogId,
        key: receipt.key,
        etag: receipt.etag
      }))
    }
  })
